      "title": "Ensure PostgreSQL database 'log_connections' flag is set to 'on'",
      "resource": "google_sql_database_instance.trading_database",
      "severity": "MEDIUM",
      "explanation": "The 'log_connections' flag is set to 'off', which may hinder auditing and troubleshooting capabilities."
    },
    {
      "check_id": "CKV_GCP_51",
      "title": "Ensure PostgreSQL database 'log_checkpoints' flag is set to 'on'",
      "resource": "google_sql_database_instance.trading_database",
      "severity": "MEDIUM",
      "explanation": "The 'log_checkpoints' flag is not set to 'on', which may lead to missing checkpoint logs."
    },
    {
      "check_id": "CKV_GCP_53",
      "title": "Ensure PostgreSQL database 'log_disconnections' flag is set to 'on'",
      "resource": "google_sql_database_instance.trading_database",
      "severity": "MEDIUM",
      "explanation": "The 'log_disconnections' flag is not set to 'on', which may hinder auditing and troubleshooting capabilities."
    },
    {
      "check_id": "CKV_GCP_54",
      "title": "Ensure PostgreSQL database 'log_lock_waits' flag is set to 'on'",
      "resource": "google_sql_database_instance.trading_database",
      "severity": "MEDIUM",
      "explanation": "The 'log_lock_waits' flag is not set to 'on', which may lead to missing lock wait logs."
    },
    {
      "check_id": "CKV2_GCP_13",
      "title": "Ensure PostgreSQL database flag 'log_duration' is set to 'on'",
      "resource": "google_sql_database_instance.trading_database",
      "severity": "MEDIUM",
      "explanation": "The 'log_duration' flag is not set to 'on', which may hinder performance monitoring and troubleshooting."
    }
  ],
  "patched_code": "resource \"google_sql_database_instance\" \"trading_database\" {\n  name             = \"real-time-financial-trading-platform-database-trading\"\n  database_version = \"POSTGRES_13\"\n  region           = var.region\n  deletion_protection = false\n  settings {\n    tier = \"db-n1-standard-2\"\n    ip_configuration {\n      ipv4_enabled    = false\n      private_network = google_compute_network.trading_platform_vpc.id\n    }\n    database_flags {\n      name  = \"log_connections\"\n      value = \"on\"\n    }\n    database_flags {\n      name  = \"log_checkpoints\"\n      value = \"on\"\n    }\n    database_flags {\n      name  = \"log_disconnections\"\n      value = \"on\"\n    }\n    database_flags {\n      name  = \"log_lock_waits\"\n      value = \"on\"\n    }\n    database_flags {\n      name  = \"log_duration\"\n      value = \"on\"\n    }\n    backup_configuration {\n      enabled                        = true\n      start_time                     = \"03:00\"\n      point_in_time_recovery_enabled = true\n    }\n  }\n  depends_on = [google_service_networking_connection.private_vpc_connection]\n}",
  "fix_summary": "Enabled PostgreSQL logging flags 'log_connections', 'log_checkpoints', 'log_disconnections', 'log_lock_waits', and 'log_duration' to improve auditing, troubleshooting, and performance monitoring."
}
